<?php
declare(strict_types=1);

/** Escapes nullable text and numeric values returned by Supabase without type errors. */
function h(mixed $value): string { return htmlspecialchars($value === null ? '' : (string)$value, ENT_QUOTES, 'UTF-8'); }
function doctor_nav(string $active): array {
    return [
        'doctor_dashboard'=>'Overview', 'doctor_patients'=>'My patients', 'doctor_records'=>'Shared records',
        'doctor_appointments'=>'Appointments', 'doctor_notes'=>'Clinical notes', 'doctor_profile'=>'My profile',
        'doctor_verification'=>'Verification', 'doctor_security'=>'Security',
    ];
}
function doctor_patient_access(Supabase $sb, string $doctorId, string $patientId): bool {
    $rows=$sb->db('GET','record_sharing','?select=id,expires_at&doctor_id=eq.'.rawurlencode($doctorId).'&patient_id=eq.'.rawurlencode($patientId).'&status=eq.active&limit=1');
    return !empty($rows) && (empty($rows[0]['expires_at']) || strtotime((string)$rows[0]['expires_at']) > time());
}
function doctor_portal(): void {
    require_role('doctor');
    $sb=new Supabase(); $doctorId=(string)user()['id'];
    $page=$_GET['page'] ?? 'doctor_dashboard';
    $allowed=array_keys(doctor_nav(''));
    if (!in_array($page,$allowed,true)) $page='doctor_dashboard';
    if ($_SERVER['REQUEST_METHOD']==='POST') {
        $form=$_POST['form'] ?? '';
        try {
            if ($form==='password_change') {
                change_password((string)($_POST['current_password'] ?? ''),(string)($_POST['new_password'] ?? ''),(string)($_POST['confirm_password'] ?? ''));
                flash('success','Password changed. Please sign in again.'); redirect('?page=login');
            }
            if ($form==='doctor_profile') {
                $specializations=['General Physician','Cardiologist','Dermatologist','Orthopedic Specialist','Gynecologist / Obstetrician','Pediatrician','Neurologist','Dentist','Ophthalmologist','ENT Specialist','Psychiatrist','Radiologist','General Surgeon','Other'];
                $specialization=in_array($_POST['specialization'] ?? '',$specializations,true) ? $_POST['specialization'] : 'Other';
                $sb->db('PATCH','profiles','?id=eq.'.rawurlencode($doctorId), ['full_name'=>trim($_POST['full_name'] ?? ''),'phone'=>trim($_POST['phone'] ?? ''),'address'=>trim($_POST['address'] ?? ''),'professional_title'=>trim($_POST['professional_title'] ?? ''),'specialization'=>$specialization,'specialization_other'=>trim($_POST['specialization_other'] ?? ''),'clinic_name'=>trim($_POST['clinic_name'] ?? ''),'qualification'=>trim($_POST['qualification'] ?? ''),'license_number'=>trim($_POST['license_number'] ?? '')]);
                profile(true); flash('success','Your clinician profile was updated.');
            }
            if ($form==='doctor_credential') {
                $upload=validated_medical_upload($_FILES['credential'] ?? []);
                $path=$doctorId.'/credentials/'.bin2hex(random_bytes(16)).'.'.$upload['extension'];
                $sb->storageUpload($path,(string)file_get_contents($upload['tmp_name']),$upload['mime']);
                $sb->db('PATCH','profiles','?id=eq.'.rawurlencode($doctorId),['credential_path'=>$path,'credential_document_type'=>trim((string)($_POST['credential_document_type'] ?? 'Professional credential')),'credential_number'=>trim((string)($_POST['credential_number'] ?? '')),'issuing_institution'=>trim((string)($_POST['issuing_institution'] ?? ''))]);
                profile(true); flash('success','Credential document submitted for administrator review.');
            }
            if ($form==='note') {
                $patientId=(string)($_POST['patient_id'] ?? '');
                if (!doctor_patient_access($sb,$doctorId,$patientId)) throw new RuntimeException('This patient has not shared access with you.');
                $noteText=trim($_POST['note_text'] ?? '');
                if (mb_strlen($noteText) < 5 || mb_strlen($noteText) > 5000) throw new RuntimeException('Please enter a clinical note between 5 and 5,000 characters.');
                $sb->db('POST','doctor_notes','', [[
                    'doctor_id'=>$doctorId,'patient_id'=>$patientId,'diagnosis'=>trim($_POST['diagnosis'] ?? ''),
                    'treatment_plan'=>trim($_POST['treatment_plan'] ?? ''),'note_type'=>trim($_POST['note_type'] ?? 'Clinical note'),'note_text'=>$noteText
                ]]); flash('success','Clinical note saved securely.');
            }
            if ($form==='appointment_status') {
                $id=(string)($_POST['id'] ?? '');
                $sb->db('PATCH','appointments','?id=eq.'.rawurlencode($id).'&doctor_id=eq.'.rawurlencode($doctorId), ['status'=>$_POST['status'] ?? 'scheduled']);
                flash('success','Appointment status updated.');
            }
        } catch(Throwable $e) { flash('danger',safe_error_message($e)); }
        redirect('?page='.urlencode($_POST['return_page'] ?? $page));
    }
    $profile=profile() ?? []; $nav=doctor_nav($page);
    if ($page === 'doctor_verification') {
        head('Credential verification');
        $status=(string)($profile['verification_status'] ?? 'pending'); ?>
        <div class="container py-5"><div class="card doctor-card p-4 mx-auto" style="max-width:720px"><span class="tag"><?=$status === 'verified' ? '✓ VERIFIED CLINICIAN' : '◷ '.strtoupper(h($status))?></span><h1 class="h3 mt-3">Credential verification</h1><p class="text-muted"><?=$status === 'verified' ? 'Your professional credentials have been approved by a reviewer.' : 'A credential upload is not automatic approval. Complete your professional profile and submit documents for a reviewer to assess.'?></p><?php if($status !== 'verified'): ?><form method="post" enctype="multipart/form-data" class="row g-3 border-top pt-3"><input type="hidden" name="form" value="doctor_credential"><input type="hidden" name="return_page" value="doctor_verification"><div class="col-md-6"><label class="form-label">Credential document</label><input class="form-control" type="file" name="credential" accept="application/pdf,image/jpeg,image/png,image/webp" required></div><div class="col-md-6"><label class="form-label">Document type</label><input class="form-control" name="credential_document_type" placeholder="Licence / degree / certificate" required></div><div class="col-md-6"><label class="form-label">Document number</label><input class="form-control" name="credential_number"></div><div class="col-md-6"><label class="form-label">Issuing institution</label><input class="form-control" name="issuing_institution"></div><div><button class="btn btn-primary">Submit for review</button></div></form><?php endif ?></div></div><?php foot(); return;
    }
    if ($page === 'doctor_profile') {
        $specialties=['General Physician','Cardiologist','Dermatologist','Orthopedic Specialist','Gynecologist / Obstetrician','Pediatrician','Neurologist','Dentist','Ophthalmologist','ENT Specialist','Psychiatrist','Radiologist','General Surgeon','Other'];
        head('Doctor profile'); ?>
        <div class="container py-5"><div class="card doctor-card p-4 mx-auto" style="max-width:900px"><div class="d-flex justify-content-between align-items-start mb-4"><div><span class="tag"><?=($profile['verification_status'] ?? 'pending') === 'verified' ? '✓ VERIFIED CLINICIAN' : '◷ VERIFICATION PENDING'?></span><h1 class="h3 mt-3 mb-1"><?=h($profile['full_name'] ?? 'Doctor')?></h1><p class="text-muted mb-0"><?=h($profile['specialization'] ?? 'Complete professional profile')?></p></div><a class="btn btn-sm btn-outline-primary" href="?page=doctor_verification">Verification</a></div><form method="post" class="row g-3"><input type="hidden" name="form" value="doctor_profile"><input type="hidden" name="return_page" value="doctor_profile"><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="full_name" value="<?=h($profile['full_name'] ?? '')?>" required></div><div class="col-md-3"><label class="form-label">Professional title</label><input class="form-control" name="professional_title" value="<?=h($profile['professional_title'] ?? '')?>" placeholder="Dr."></div><div class="col-md-3"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=h($profile['phone'] ?? '')?>"></div><div class="col-md-6"><label class="form-label">Specialization</label><select class="form-select" name="specialization"><?php foreach($specialties as $s): ?><option <?=$s===($profile['specialization'] ?? '')?'selected':''?>><?=h($s)?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Other specialization</label><input class="form-control" name="specialization_other" value="<?=h($profile['specialization_other'] ?? '')?>"></div><div class="col-md-6"><label class="form-label">Clinic / hospital</label><input class="form-control" name="clinic_name" value="<?=h($profile['clinic_name'] ?? '')?>"></div><div class="col-md-6"><label class="form-label">Qualification</label><input class="form-control" name="qualification" value="<?=h($profile['qualification'] ?? '')?>"></div><div class="col-md-6"><label class="form-label">Registration / licence number</label><input class="form-control" name="license_number" value="<?=h($profile['license_number'] ?? '')?>"></div><div class="col-md-6"><label class="form-label">Clinic address</label><input class="form-control" name="address" value="<?=h($profile['address'] ?? '')?>"></div><div class="col-12"><button class="btn btn-primary">Save professional profile</button></div></form></div></div><?php foot(); return;
    }
    head('Clinician portal · '.($nav[$page] ?? 'CareNest')); ?>
