<div class="clinician-shell"><header class="clinician-top"><div class="container d-flex align-items-center justify-content-between"><a class="text-white text-decoration-none fs-4 fw-bold" href="?page=doctor_dashboard"><span class="doctor-mark">+</span>CareNest <small class="fs-6 fw-normal opacity-75">Clinician</small></a><div class="d-flex align-items-center gap-3"><span class="d-none d-md-inline">Dr. <?=h($profile['full_name'] ?? 'Clinician')?></span><a class="btn btn-sm btn-outline-light" href="?action=logout">Sign out</a></div></div></header>
<main class="container py-4 py-md-5"><div class="row g-4"><aside class="col-lg-3"><nav class="doctor-side"><div class="px-2 pt-2 pb-3"><span class="tag"><?=($profile['verification_status'] ?? 'pending') === 'verified' ? '✓ VERIFIED CLINICIAN' : '◷ '.strtoupper(str_replace('_',' ',(string)($profile['verification_status'] ?? 'pending')))?></span><div class="fw-bold mt-2"><?=h($profile['full_name'] ?? 'Doctor')?></div><div class="small text-muted"><?=h($profile['specialization'] ?? 'Professional profile incomplete')?></div></div><?php foreach($nav as $key=>$name): ?><a class="<?=$page===$key?'active':''?>" href="?page=<?=$key?>"><?=$name?></a><?php endforeach ?></nav></aside><section class="col-lg-9">
<?php if($page==='doctor_dashboard'):
    $shares=$sb->db('GET','record_sharing','?select=patient_id,shared_at,expires_at&doctor_id=eq.'.rawurlencode($doctorId).'&status=eq.active');
    $appointments=$sb->db('GET','appointments','?select=*&doctor_id=eq.'.rawurlencode($doctorId).'&order=scheduled_at.asc&limit=5'); ?>
    <span class="text-uppercase small fw-bold text-success">Clinician workspace</span><h1 class="display-6 fw-bold mt-2">Good day, Dr. <?=h(explode(' ',trim($profile['full_name'] ?? 'Doctor'))[0])?>.</h1><p class="text-muted mb-4">Review only the records that patients have explicitly shared with you.</p>
    <div class="row g-3 mb-4"><div class="col-md-6"><div class="doctor-stat"><div class="text-muted small">PATIENTS WITH ACTIVE ACCESS</div><div class="display-6 fw-bold"><?=count($shares)?></div></div></div><div class="col-md-6"><div class="doctor-stat"><div class="text-muted small">UPCOMING APPOINTMENTS</div><div class="display-6 fw-bold"><?=count($appointments)?></div></div></div></div>
    <div class="card doctor-card p-4"><div class="d-flex justify-content-between"><h2 class="h5">Upcoming appointments</h2><a href="?page=doctor_appointments">View all</a></div><?php if(!$appointments): ?><p class="text-muted mb-0">No appointments are assigned to you yet.</p><?php endif; foreach($appointments as $a): ?><div class="border-top pt-3 mt-3"><strong><?=h($a['reason'] ?? 'Patient appointment')?></strong><span class="ms-2 tag"><?=h($a['status'] ?? 'scheduled')?></span><div class="small text-muted mt-1"><?=h($a['scheduled_at'] ?? '')?></div></div><?php endforeach ?></div>
<?php elseif($page==='doctor_patients'):
    $shares=$sb->db('GET','record_sharing','?select=patient_id,shared_at,expires_at&doctor_id=eq.'.rawurlencode($doctorId).'&status=eq.active&order=shared_at.desc'); ?>
    <span class="text-uppercase small fw-bold text-success">Consent-based access</span><h1 class="display-6 fw-bold mt-2">My patients</h1><p class="text-muted">These people granted you access. You cannot browse any other patient data.</p>
    <?php if(!$shares): ?><div class="card doctor-card p-4 text-muted">No patient has shared records with you yet. Ask the patient to use “Share with doctor” and enter your registered email.</div><?php endif; foreach($shares as $share): $people=$sb->db('GET','profiles','?select=full_name,email,blood_group,allergies&id=eq.'.rawurlencode($share['patient_id']).'&limit=1'); $person=$people[0]??[]; ?><div class="patient-row"><div class="d-flex justify-content-between align-items-start"><div><strong><?=h($person['full_name'] ?? 'Patient')?></strong><div class="small text-muted"><?=h($person['email'] ?? '')?></div><div class="small mt-2">Blood group: <?=h($person['blood_group'] ?? 'Not recorded')?> · Allergies: <?=h($person['allergies'] ?? 'Not recorded')?></div></div><a class="btn btn-sm btn-primary" href="?page=doctor_records&patient_id=<?=urlencode($share['patient_id'])?>">Open shared record</a></div></div><?php endforeach ?>
<?php elseif($page==='doctor_records'):
    $patientId=(string)($_GET['patient_id'] ?? ''); if(!$patientId || !doctor_patient_access($sb,$doctorId,$patientId)): ?><div class="alert alert-warning">Choose a patient from <a href="?page=doctor_patients">My patients</a>. Access is required before records can be shown.</div><?php else: $people=$sb->db('GET','profiles','?select=full_name,email,blood_group,allergies&id=eq.'.rawurlencode($patientId).'&limit=1');$person=$people[0]??[];$records=$sb->db('GET','medical_records','?select=*&patient_id=eq.'.rawurlencode($patientId).'&order=created_at.desc');$metrics=$sb->db('GET','health_metrics','?select=*&patient_id=eq.'.rawurlencode($patientId).'&order=measured_at.desc&limit=8'); ?>
<a class="small" href="?page=doctor_patients">← My patients</a><h1 class="display-6 fw-bold mt-2"><?=h($person['full_name'] ?? 'Patient')?>’s shared health record</h1><div class="card doctor-card p-4 mb-4"><strong>Safety information</strong><div class="mt-2">Blood group: <?=h($person['blood_group'] ?? 'Not recorded')?> · Allergies: <?=h($person['allergies'] ?? 'Not recorded')?></div></div><div class="row g-3"><div class="col-md-6"><div class="card doctor-card p-4 h-100"><h2 class="h5">Documents</h2><?php if(!$records): ?><p class="text-muted">No documents shared.</p><?php endif; foreach($records as $r): ?><div class="border-top pt-2 mt-2"><strong><?=h($r['title'] ?? $r['record_title'] ?? 'Medical record')?></strong><div class="small text-muted"><?=h($r['created_at'] ?? '')?></div></div><?php endforeach ?></div></div><div class="col-md-6"><div class="card doctor-card p-4 h-100"><h2 class="h5">Recent vitals</h2><?php if(!$metrics): ?><p class="text-muted">No measurements shared.</p><?php endif; foreach($metrics as $m): ?><div class="border-top pt-2 mt-2"><strong><?=h($m['metric_type'] ?? '')?>: <?=h($m['value'] ?? $m['metric_value'] ?? '')?> <?=h($m['unit'] ?? '')?></strong><div class="small text-muted"><?=h($m['measured_at'] ?? $m['recorded_at'] ?? '')?></div></div><?php endforeach ?></div></div></div><a class="btn btn-primary mt-4" href="?page=doctor_notes&patient_id=<?=urlencode($patientId)?>">Add clinical note</a><?php endif ?>
<?php elseif($page==='doctor_appointments'):
    $items=$sb->db('GET','appointments','?select=*&doctor_id=eq.'.rawurlencode($doctorId).'&order=scheduled_at.asc'); ?><h1 class="display-6 fw-bold">Appointments</h1><p class="text-muted">Update only appointments assigned to your account.</p><?php if(!$items): ?><div class="card doctor-card p-4 text-muted">There are no assigned appointments.</div><?php endif; foreach($items as $a): ?><div class="patient-row"><strong><?=h($a['reason'] ?? 'Appointment')?></strong><div class="small text-muted mb-2"><?=h($a['scheduled_at'] ?? '')?></div><form method="post" class="d-flex gap-2"><input type="hidden" name="form" value="appointment_status"><input type="hidden" name="return_page" value="doctor_appointments"><input type="hidden" name="id" value="<?=h($a['id'])?>"><select class="form-select form-select-sm" name="status" style="max-width:180px"><?php foreach(['scheduled','confirmed','completed','cancelled'] as $status): ?><option <?=$status===($a['status']??'')?'selected':''?>><?=$status?></option><?php endforeach ?></select><button class="btn btn-sm btn-primary">Save</button></form></div><?php endforeach ?>
<?php elseif($page==='doctor_notes'):
    $patientId=(string)($_GET['patient_id'] ?? ''); $can=$patientId && doctor_patient_access($sb,$doctorId,$patientId); $notes=$sb->db('GET','doctor_notes','?select=*&doctor_id=eq.'.rawurlencode($doctorId).'&order=created_at.desc&limit=20'); ?><h1 class="display-6 fw-bold">Clinical notes</h1><?php if($can): ?><div class="card doctor-card p-4 mb-4"><h2 class="h5">New note</h2><form method="post" class="row g-3"><input type="hidden" name="form" value="note"><input type="hidden" name="return_page" value="doctor_notes"><input type="hidden" name="patient_id" value="<?=h($patientId)?>"><div class="col-md-6"><input class="form-control" name="diagnosis" placeholder="Diagnosis / clinical impression"></div><div class="col-md-6"><input class="form-control" name="treatment_plan" placeholder="Treatment plan"></div><div class="col-12"><textarea class="form-control" rows="4" name="note_text" placeholder="Private clinical note" required></textarea></div><div><button class="btn btn-primary">Save note</button></div></form></div><?php else: ?><div class="alert alert-info">Open a shared patient record first to add a note.</div><?php endif; foreach($notes as $note): ?><div class="patient-row"><strong><?=h($note['diagnosis'] ?: 'Clinical note')?></strong><div class="mt-2"><?=nl2br(h($note['note_text']))?></div><div class="small text-muted mt-2"><?=h($note['created_at'])?></div></div><?php endforeach ?>
