<?php else: ?><h1 class="display-6 fw-bold">Security</h1><div class="row g-4"><div class="col-lg-7"><div class="card doctor-card p-4"><h2 class="h5">Change password</h2><p class="small text-muted">Confirm your current password before choosing a new one.</p><form method="post" class="row g-3"><input type="hidden" name="form" value="password_change"><input type="hidden" name="return_page" value="doctor_security"><div class="col-12"><input class="form-control" type="password" name="current_password" placeholder="Current password" required></div><div class="col-md-6"><input class="form-control" type="password" name="new_password" placeholder="New password (10+ characters)" minlength="10" required></div><div class="col-md-6"><input class="form-control" type="password" name="confirm_password" placeholder="Confirm new password" minlength="10" required></div><div><button class="btn btn-primary">Update password</button></div></form></div></div><div class="col-lg-5"><div class="card doctor-card p-4 h-100"><h2 class="h5">Protected clinician access</h2><p class="text-muted mb-0">You can only open records that a patient has actively shared with you. Signing out clears this browser session.</p></div></div></div><?php endif ?>
